#[derive(Clone)] pub struct ConfirmDelete { pub paths: Vec<PathBuf>, pub permanent: bool, }
impl ExplorerApp {
fn new(start_path: PathBuf, config: AppConfig, _cc: &eframe::CreationContext<'_>) -> Self { let show_hidden=config.show_hidden; let dual_pane=config.dual_pane; let sort_by=config.sort_by; let sort_desc=config.sort_desc; let font_path_edit=config.font_custom_path.clone().unwrap_or_default(); let tab=Tab::new(start_path.clone(), show_hidden, sort_by, sort_desc); let pane2=if dual_pane{Some(Tab::new(start_path.clone(),show_hidden,sort_by,sort_desc))}else{None}; let (bg_tx,bg_rx)=commands::channel(); let mut app=Self{tabs:vec![tab],active:0,pane2,active_pane:0,address:start_path.display().to_string(),search_query:String::new(),search_results:vec![],searching:false,pasting:false,status:"準備完了".into(),config,clipboard:None,show_hidden,dual_pane,preview_text:String::new(),rename_buffer:String::new(),renaming:false,new_folder_name:"新しいフォルダ".into(),show_new_folder_dialog:false,last_error:None,confirm_delete:None,font_path_edit,typeahead:String::new(),typeahead_at:None,watcher:None,watcher2:None,list_gen:0,list_gen_p2:0,listing:false,listing_p2:false,bg_tx,bg_rx,icon_cache:RefCell::new(HashMap::new()),focus_request:None,scroll_to_row:None,rename_focus_once:false,new_folder_focus_once:false,pending_clipboard_text:None,}; app.config.push_recent(start_path); app.sync_watchers(); app.update_preview(); app }
fn current_tab(&self)->&Tab{ if self.active_pane==1{ if let Some(p)=&self.pane2{return p;}} &self.tabs[self.active] }
fn current_tab_mut(&mut self)->&mut Tab{ if self.active_pane==1{ if let Some(p)=self.pane2.as_mut(){return p;}} &mut self.tabs[self.active] }
fn sync_address(&mut self){ self.address=self.current_tab().current.display().to_string(); }
fn note_navigation(&mut self){ let cur=self.current_tab().current.clone(); self.config.push_recent(cur); }
fn sync_config_from_state(&mut self){ self.config.show_hidden=self.show_hidden; self.config.dual_pane=self.dual_pane; let (sort_by,sort_desc,last_path)={let tab=self.current_tab(); (tab.sort_by,tab.sort_desc,tab.current.clone())}; self.config.sort_by=sort_by; self.config.sort_desc=sort_desc; self.config.last_path=Some(last_path.clone()); self.config.push_recent(last_path); let path=self.font_path_edit.trim(); self.config.font_custom_path=if path.is_empty(){None}else{Some(path.to_string())}; }
fn apply_font_settings(&mut self, ctx:&egui::Context){ let path=self.font_path_edit.trim(); self.config.font_custom_path=if path.is_empty(){None}else{Some(path.to_string())}; if self.config.font_preset==FontPreset::Custom && path.is_empty(){ self.status="カスタムフォントのパスを指定してください".into(); return; } let msg=fonts::apply_fonts(ctx,&self.config); self.status=format!("適用しました — {msg}"); let _=self.config.save(); }
fn sync_watchers(&mut self){ let cur=self.tabs[self.active].current.clone(); let need=self.watcher.as_ref().map(|w|&w.path)!=Some(&cur); if need{ self.watcher=watch::watch_dir(self.bg_tx.clone(),cur); } if let Some(p2)=&self.pane2{ let cur2=p2.current.clone(); let need2=self.watcher2.as_ref().map(|w|&w.path)!=Some(&cur2); if need2{ self.watcher2=watch::watch_dir(self.bg_tx.clone(),cur2); } } else{ self.watcher2=None; } }
fn request_refresh_async(&mut self,is_pane2:bool){ if is_pane2{ if let Some(p2)=&self.pane2{ self.list_gen_p2+=1; let gen=self.list_gen_p2; self.listing_p2=true; commands::spawn_list(self.bg_tx.clone(),gen,true,p2.current.clone(),self.show_hidden,p2.filter.clone(),p2.sort_by,p2.sort_desc,); } } else{ let tab=&self.tabs[self.active]; self.list_gen+=1; let gen=self.list_gen; self.listing=true; commands::spawn_list(self.bg_tx.clone(),gen,false,tab.current.clone(),self.show_hidden,tab.filter.clone(),tab.sort_by,tab.sort_desc,); } }
fn poll_bg(&mut self,ctx:&egui::Context){ let mut events=Vec::new(); while let Ok(ev)=self.bg_rx.try_recv(){ events.push(ev); } for ev in events{ match ev{ BgEvent::SearchDone{query,results}=>{ if query==self.search_query{ let n=results.len(); self.search_results=results; self.searching=false; self.status=format!("検索結果: {n} 件"); } } BgEvent::PasteDone{message,ok:_,err,}=>{ self.pasting=false; if err>0{ self.last_error=Some(format!("失敗 {err} 件")); } self.status=message; self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } self.sync_watchers(); self.update_preview(); } BgEvent::FsChanged=>{ self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } } BgEvent::ListDone{generation,is_pane2,entries,error,}=>{ if is_pane2{ if generation==self.list_gen_p2{ self.listing_p2=false; if let Some(p2)=self.pane2.as_mut(){ p2.apply_list(entries,error); } self.update_preview(); } } else if generation==self.list_gen{ self.listing=false; self.tabs[self.active].apply_list(entries,error); self.sync_address(); self.update_preview(); } } } ctx.request_repaint(); } if self.searching||self.pasting||self.listing||self.listing_p2{ ctx.request_repaint(); } }
fn open_path(&mut self,path:&Path){ if path.is_dir(){ self.clear_typeahead(); self.current_tab_mut().navigate_to(path.to_path_buf()); self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); } else{ match shell::open_with_shell(path){ Ok(_)=> self.status=format!("開きました: {}",path.display()), Err(e)=> self.status=format!("開けませんでした: {e}"), } } }
fn clear_typeahead(&mut self){ self.typeahead.clear(); self.typeahead_at=None; }
fn icon_cache_key(path:&Path,is_dir:bool)->String{ if is_dir{ return "__dir__".to_string(); } let ext=path.extension().and_then(|s|s.to_str()).unwrap_or("").to_lowercase(); if ext=="exe"||ext=="ico"||ext=="lnk"{ return format!("file:{}",path.display()); } format!("ext:{ext}") }
fn get_or_load_icon(&self,ctx:&egui::Context,path:&Path,is_dir:bool)->Option<egui::TextureHandle>{ let key=Self::icon_cache_key(path,is_dir); if let Some(h)=self.icon_cache.borrow().get(&key){ return Some(h.clone()); } #[cfg(windows)]{ if let Some((rgba,w,h))=shell::icon_rgba(path,is_dir){ if w>0&&h>0&&rgba.len()==(w*h*4) as usize{ let img=egui::ColorImage::from_rgba_unmultiplied([w as usize,h as usize],&rgba); let tex=ctx.load_texture(key.clone(),img,egui::TextureOptions::LINEAR); self.icon_cache.borrow_mut().insert(key.clone(),tex.clone()); return Some(tex); } } } let _=(ctx,path,is_dir); None }
// Context7: egui-winit splits Text/Key, Text優先でIME対応。focusなしならフィルタへ直行させ競合解消
fn handle_typeahead(&mut self, ctx:&egui::Context){
    if self.renaming || self.show_new_folder_dialog || self.confirm_delete.is_some(){ return; }
    let is_typing = ctx.wants_keyboard_input();
    let mut typed=String::new(); let mut has_text=false; let mut backspace=false;
    ctx.input(|i|{ for ev in &i.events{ if let egui::Event::Key{key:egui::Key::Backspace, pressed:true, modifiers, ..}=ev{ if !modifiers.ctrl && !modifiers.command && !modifiers.alt{ backspace=true; } } } });
    if backspace && !self.typeahead.is_empty(){ self.typeahead.pop(); self.typeahead_at=Some(Instant::now()); if self.typeahead.is_empty(){ self.status="検索クリア".into(); ctx.request_repaint(); return; } } else if backspace{ return; }
    ctx.input(|i|{
        for ev in &i.events{ if let egui::Event::Text(t)=ev{ if !t.is_empty() && t.chars().all(|c|!c.is_control()){ typed.push_str(t); has_text=true; } } }
        if !has_text{ for ev in &i.events{ if let egui::Event::Key{key, pressed:true, modifiers, ..}=ev{ if modifiers.ctrl||modifiers.command||modifiers.alt{ continue; } let ch=match key{ egui::Key::A=>'a', egui::Key::B=>'b', egui::Key::C=>'c', egui::Key::D=>'d', egui::Key::E=>'e', egui::Key::F=>'f', egui::Key::G=>'g', egui::Key::H=>'h', egui::Key::I=>'i', egui::Key::J=>'j', egui::Key::K=>'k', egui::Key::L=>'l', egui::Key::M=>'m', egui::Key::N=>'n', egui::Key::O=>'o', egui::Key::P=>'p', egui::Key::Q=>'q', egui::Key::R=>'r', egui::Key::S=>'s', egui::Key::T=>'t', egui::Key::U=>'u', egui::Key::V=>'v', egui::Key::W=>'w', egui::Key::X=>'x', egui::Key::Y=>'y', egui::Key::Z=>'z', egui::Key::Num0=>'0', egui::Key::Num1=>'1', egui::Key::Num2=>'2', egui::Key::Num3=>'3', egui::Key::Num4=>'4', egui::Key::Num5=>'5', egui::Key::Num6=>'6', egui::Key::Num7=>'7', egui::Key::Num8=>'8', egui::Key::Num9=>'9', _=>continue, } ; typed.push(ch); has_text=true; } } }
    });
    if typed.is_empty() && !backspace{ if let Some(at)=self.typeahead_at{ if at.elapsed().as_millis()>1500{ self.clear_typeahead(); } else{ ctx.request_repaint_after(std::time::Duration::from_millis(100)); } } return; }
    // フィルタ統合: focusなしで printable が来たらフィルタへ直行 (日本語IMEの Text もここ)
    if !is_typing && !typed.is_empty(){
        self.focus_request=Some(FocusTarget::Filter);
        let tab=self.current_tab_mut();
        tab.filter.push_str(&typed);
        self.request_refresh_async(false);
        self.status=format!("フィルタ: '{}'", tab.filter);
        ctx.request_repaint();
        return;
    }
    if is_typing{ return; }
    // 互換: 従来typeahead継続 (現在は到達しにくい)
    if !typed.is_empty(){ if let Some(at)=self.typeahead_at{ if at.elapsed().as_millis()>1500{ self.typeahead.clear(); } } self.typeahead.push_str(&typed); self.typeahead_at=Some(Instant::now()); } else{ self.typeahead_at=Some(Instant::now()); }
    let q=self.typeahead.to_lowercase(); let entries=self.current_tab().entries.clone(); if entries.is_empty(){ return; }
    let start=self.current_tab().focus.map(|f|f+1).unwrap_or(0); let mut found=None; for o in 0..entries.len(){ let idx=(start+o)%entries.len(); if entries[idx].name.to_lowercase().starts_with(&q){ found=Some(idx); break; } } if found.is_none(){ for (idx,e) in entries.iter().enumerate(){ if e.name.to_lowercase().contains(&q){ found=Some(idx); break; } } }
    if let Some(idx)=found{ self.current_tab_mut().select_only(idx); self.scroll_to_row=Some(idx); self.update_preview(); self.status=format!("インクリメント検索: '{}' → {}", self.typeahead, entries[idx].name); } else{ self.status=format!("該当なし: '{}'", self.typeahead); } ctx.request_repaint();
}
fn update_preview(&mut self){ if let Some(entry)=self.current_tab().primary_selected().cloned(){ if entry.is_dir{ let count=std::fs::read_dir(&entry.path).map(|rd| rd.count()).unwrap_or(0); self.preview_text=format!("フォルダ: {}\nパス: {}\n\n含まれる項目: {} 個", entry.name, entry.path.display(), count); } else{ let ext=entry.ext.to_lowercase(); let text_exts=["txt","md","rs","toml","json","yaml","yml","csv","log","ini","cfg","py","js","ts","html","css","xml","bat","ps1","sh","go","java","c","cpp","h","hpp","cs",]; if text_exts.contains(&ext.as_str()){ match std::fs::read_to_string(&entry.path){ Ok(s)=> self.preview_text=fs_ops::truncate_chars(&s,4000), Err(e)=> self.preview_text=format!("読み込み失敗: {e}"), } } else if ["png","jpg","jpeg","gif","bmp","webp","ico"].contains(&ext.as_str()){ self.preview_text=format!("画像ファイル: {}\nサイズ: {}\nパス: {}", entry.name, fs_ops::humansize(entry.size), entry.path.display()); } else{ self.preview_text=format!("ファイル: {}\nサイズ: {}\n種類: {}\n更新: {}\nパス: {}", entry.name, fs_ops::humansize(entry.size), entry.ext, fs_ops::fmt_time(entry.modified), entry.path.display()); } } } else{ let cur=self.current_tab().current.clone(); let free=fs_ops::free_space(&cur).unwrap_or_default(); let n=self.current_tab().entries.len(); let tip=if self.typeahead.is_empty(){ "文字を入力でインクリメント検索".to_string() } else{ format!("検索中: '{}'", self.typeahead) }; self.preview_text=format!("場所: {cur}\n\n項目数: {n}\n{free}\n\nヒント:\n• {tip}\n• Ctrl+L アドレス / Ctrl+F 検索\n• Home/End/PgUp/PgDn · Shift+矢印 範囲\n• Ctrl+I 反転 · Ctrl+Shift+C パスコピー\n• Del=ごみ箱 · Shift+Del=完全削除 · F10 2ペイン · Ctrl+H 隠し", cur=cur.display(), tip=tip); } }
fn run_command(&mut self, cmd:Command){ match cmd{ Command::Copy=> self.do_clipboard(ClipboardMode::Copy), Command::Cut=> self.do_clipboard(ClipboardMode::Cut), Command::Paste=> self.do_paste(), Command::Delete{permanent}=> self.ask_delete(permanent), Command::ConfirmDelete{permanent}=> self.do_delete_confirmed(permanent), Command::CancelDialog=>{ self.confirm_delete=None; self.show_new_folder_dialog=false; self.renaming=false; } Command::Rename=>{ if let Some(e)=self.current_tab().primary_selected(){ self.rename_buffer=e.name.clone(); self.renaming=true; self.rename_focus_once=true; } else{ self.status="選択がありません".into(); } } Command::NewFolder=>{ self.new_folder_name="新しいフォルダ".into(); self.show_new_folder_dialog=true; self.new_folder_focus_once=true; } Command::NewTextFile=> self.do_new_text_file(), Command::SelectAll=>{ self.current_tab_mut().select_all(); self.update_preview(); self.status=format!("{} 件選択",self.current_tab().selected.len()); } Command::InvertSelection=>{ self.current_tab_mut().invert_selection(); self.update_preview(); self.status=format!("選択反転: {} 件",self.current_tab().selected.len()); } Command::Refresh=>{ self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } self.status="更新中…".into(); } Command::GoUp=>{ self.clear_typeahead(); if self.current_tab_mut().go_up(){ self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); } } Command::GoBack=>{ self.clear_typeahead(); if self.current_tab_mut().go_back(){ self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); } } Command::GoForward=>{ self.clear_typeahead(); if self.current_tab_mut().go_forward(){ self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); } } Command::GoHome=>{ if let Some(home)=dirs::home_dir(){ self.clear_typeahead(); self.current_tab_mut().navigate_to(home); self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); self.status="ホームへ移動".into(); } } Command::OpenPrimary=>{ if let Some(p)=self.current_tab_mut().enter_primary(){ let _=shell::open_with_shell(&p); } else{ self.clear_typeahead(); self.sync_address(); self.note_navigation(); self.sync_watchers(); self.update_preview(); } } Command::AddBookmark=> self.add_bookmark(), Command::Search=> self.do_search(), Command::CopyPath=> self.copy_selected_paths(false), Command::CopyName=> self.copy_selected_paths(true), Command::ToggleHidden=>{ self.show_hidden=!self.show_hidden; for t in &mut self.tabs{ t.show_hidden=self.show_hidden; } if let Some(p)=self.pane2.as_mut(){ p.show_hidden=self.show_hidden; } self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } self.status=if self.show_hidden{ "隠しファイルを表示".into() } else{ "隠しファイルを非表示".into() }; } Command::TogglePreview=>{ self.config.show_preview=!self.config.show_preview; } Command::ToggleDualPane=>{ let on=!self.dual_pane; self.set_dual_pane(on); self.status=if on{ "2ペイン ON".into() } else{ "2ペイン OFF".into() }; } Command::FocusAddress=> self.focus_request=Some(FocusTarget::Address), Command::FocusSearch=> self.focus_request=Some(FocusTarget::Search), Command::FocusFilter=> self.focus_request=Some(FocusTarget::Filter), } }
fn copy_selected_paths(&mut self,names_only:bool){ let paths=self.current_tab().selected_paths(); let s=if paths.is_empty(){ if names_only{ self.current_tab().current.file_name().map(|n|n.to_string_lossy().to_string()).unwrap_or_else(||self.current_tab().current.display().to_string()) } else{ self.current_tab().current.display().to_string() } } else{ paths.iter().map(|p|{ if names_only{ p.file_name().map(|n|n.to_string_lossy().to_string()).unwrap_or_else(||p.display().to_string()) } else{ p.display().to_string() } }).collect::<Vec<_>>().join("\n") }; let n=if paths.is_empty(){1} else{paths.len()}; self.status=if names_only{ format!("名前をコピー: {n} 件") } else{ format!("パスをコピー: {n} 件") }; self.pending_clipboard_text=Some(s); }
fn do_clipboard(&mut self,mode:ClipboardMode){ let paths=self.current_tab().selected_paths(); if paths.is_empty(){ self.status="選択がありません".into(); return; } let n=paths.len(); self.clipboard=Some(Clipboard::new(paths,mode)); let m=if mode==ClipboardMode::Copy{ "コピー" } else{ "切り取り" }; self.status=format!("{m}しました: {n} 件"); }
fn do_paste(&mut self){ let Some(cb)=self.clipboard.clone() else{ self.status="クリップボードが空です".into(); return; }; if self.pasting{ self.status="貼り付け処理中です…".into(); return; } let dest=self.current_tab().current.clone(); self.pasting=true; self.status=format!("貼り付け中… ({} 件)",cb.paths.len()); commands::spawn_paste(self.bg_tx.clone(),cb.paths,cb.mode,dest); if matches!(cb.mode,ClipboardMode::Cut){ self.clipboard=None; } }
fn ask_delete(&mut self,permanent:bool){ let paths=self.current_tab().selected_paths(); if paths.is_empty(){ self.status="選択がありません".into(); return; } self.confirm_delete=Some(ConfirmDelete{paths,permanent}); }
fn do_delete_confirmed(&mut self,permanent:bool){ let Some(conf)=self.confirm_delete.take() else{ return; }; let permanent=permanent||conf.permanent; let res=if permanent{ fs_ops::permanent_delete(&conf.paths) } else{ fs_ops::trash_paths(&conf.paths) }; match res{ Ok(())=>{ let n=conf.paths.len(); self.status=if permanent{ format!("完全に削除: {n} 件") } else{ format!("ごみ箱へ移動: {n} 件") }; self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } } Err(e)=>{ self.last_error=Some(e.to_string()); self.status=format!("削除失敗: {e}"); } } }
fn do_rename(&mut self){ let Some(entry)=self.current_tab().primary_selected().cloned() else{ self.renaming=false; return; }; let Some(new_name)=fs_ops::sanitize_filename(&self.rename_buffer) else{ self.status="不正な名前です（\\/:*?\"<>| や予約名は使えません）".into(); return; }; if new_name==entry.name{ self.renaming=false; return; } let parent=entry.path.parent().unwrap_or(Path::new(".")); let new_path=parent.join(&new_name); if new_path.exists(){ self.status="同名のファイル/フォルダが既に存在します".into(); return; } match std::fs::rename(&entry.path,&new_path){ Ok(())=>{ self.status=format!("名前変更: {} → {new_name}",entry.name); self.renaming=false; self.request_refresh_async(false); if self.dual_pane{ self.request_refresh_async(true); } } Err(e)=> self.status=format!("名前変更失敗: {e}"), } }
fn do_new_folder(&mut self){ let Some(name)=fs_ops::sanitize_filename(&self.new_folder_name) else{ self.status="不正なフォルダ名です".into(); return; }; let p=self.current_tab().current.join(&name); if p.exists(){ self.status="同名のフォルダが既に存在します".into(); return; } match std::fs::create_dir(&p){ Ok(())=>{ self.status=format!("作成しました: {}",p.display()); self.show_new_folder_dialog=false; self.request_refresh_async(false); } Err(e)=> self.status=format!("作成失敗: {e}"), } }
fn do_new_text_file(&mut self){ let dir=self.current_tab().current.clone(); let mut p=dir.join("新しいテキスト ドキュメント.txt"); let mut c=1; while p.exists(){ p=dir.join(format!("新しいテキスト ドキュメント ({c}).txt")); c+=1; if c>999{ break; } } match std::fs::write(&p,""){ Ok(())=>{ self.status=format!("作成: {}",p.display()); self.request_refresh_async(false); } Err(e)=> self.status=format!("作成失敗: {e}"), } }
fn do_search(&mut self){ let q=self.search_query.trim().to_string(); if q.is_empty(){ self.search_results.clear(); return; } if self.searching{ return; } self.searching=true; self.status=format!("検索中: {q} …"); let root=self.current_tab().current.clone(); commands::spawn_search(self.bg_tx.clone(),root,q); }
fn add_bookmark(&mut self){ let cur=self.current_tab().current.clone(); let name=cur.file_name().and_then(|s|s.to_str()).unwrap_or("ブックマーク").to_string(); if self.config.bookmarks.iter().any(|b|b.path==cur){ self.status="既にブックマーク済みです".into(); return; } self.config.bookmarks.push(Bookmark{name:name.clone(),path:cur,}); match self.config.save(){ Ok(())=> self.status=format!("ブックマーク追加: {name}"), Err(e)=> self.status=e, } }
fn handle_shortcuts(&mut self, ctx:&egui::Context){ if self.renaming||self.show_new_folder_dialog||self.confirm_delete.is_some(){ if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Escape)){ self.run_command(Command::CancelDialog); } if self.renaming && ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Enter)){ self.do_rename(); } if self.show_new_folder_dialog && ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Enter)){ self.do_new_folder(); } return; } { let del_plain=ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Delete)); let del_shift=ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::Delete)); if del_plain||del_shift{ let permanent=del_shift||ctx.input(|i|i.modifiers.shift); let typing_now=ctx.wants_keyboard_input(); if !typing_now||permanent{ self.run_command(Command::Delete{permanent}); } } } let typing=ctx.wants_keyboard_input(); if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::L)){ self.run_command(Command::FocusAddress); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::F)){ self.run_command(Command::FocusSearch); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::T)){ let cur=self.current_tab().current.clone(); let sh=self.show_hidden; let sb=self.current_tab().sort_by; let sd=self.current_tab().sort_desc; self.tabs.push(Tab::new(cur,sh,sb,sd)); self.active=self.tabs.len()-1; self.active_pane=0; self.sync_address(); self.sync_watchers(); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::W)) && self.tabs.len()>1{ self.tabs.remove(self.active); if self.active>=self.tabs.len(){ self.active=self.tabs.len()-1; } self.active_pane=0; self.sync_address(); self.sync_watchers(); self.update_preview(); } if typing{ return; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::A)){ self.run_command(Command::SelectAll); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::I)){ self.run_command(Command::InvertSelection); } if ctx.input_mut(|i|{ i.consume_key(egui::Modifiers::CTRL|egui::Modifiers::SHIFT,egui::Key::C) }){ self.run_command(Command::CopyPath); } else if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::C)){ self.run_command(Command::Copy); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::X)){ self.run_command(Command::Cut); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::V)){ self.run_command(Command::Paste); } if ctx.input_mut(|i|{ i.consume_key(egui::Modifiers::CTRL|egui::Modifiers::SHIFT,egui::Key::N) }){ self.run_command(Command::NewFolder); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::F2)){ self.run_command(Command::Rename); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::F5)){ self.run_command(Command::Refresh); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::F10)){ self.run_command(Command::ToggleDualPane); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::H)){ self.run_command(Command::ToggleHidden); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::CTRL,egui::Key::P)){ self.run_command(Command::TogglePreview); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::ALT,egui::Key::ArrowUp)){ self.run_command(Command::GoUp); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::ALT,egui::Key::ArrowLeft)){ self.run_command(Command::GoBack); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::ALT,egui::Key::ArrowRight)){ self.run_command(Command::GoForward); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::ALT,egui::Key::Home)){ self.run_command(Command::GoHome); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Enter)){ self.run_command(Command::OpenPrimary); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Escape)){ if !self.typeahead.is_empty(){ self.clear_typeahead(); self.status="検索クリア".into(); } else if !self.current_tab().selected.is_empty(){ self.current_tab_mut().clear_selection(); self.update_preview(); } else{ self.search_results.clear(); self.search_query.clear(); self.update_preview(); } } let shift=ctx.input(|i|i.modifiers.shift); let mut moved=false; if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::ArrowDown))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::ArrowDown)){ self.current_tab_mut().move_focus_by(1,shift); moved=true; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::ArrowUp))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::ArrowUp)){ self.current_tab_mut().move_focus_by(-1,shift); moved=true; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::PageDown))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::PageDown)){ self.current_tab_mut().move_focus_by(20,shift); moved=true; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::PageUp))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::PageUp)){ self.current_tab_mut().move_focus_by(-20,shift); moved=true; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Home))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::Home)){ self.current_tab_mut().focus_first(shift); moved=true; } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::End))||ctx.input_mut(|i|i.consume_key(egui::Modifiers::SHIFT,egui::Key::End)){ self.current_tab_mut().focus_last(shift); moved=true; } if moved{ self.scroll_to_row=self.current_tab().focus; self.update_preview(); } if ctx.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Backspace)) && self.typeahead.is_empty(){ self.run_command(Command::GoUp); } }
fn set_dual_pane(&mut self,on:bool){ self.dual_pane=on; if on{ if self.pane2.is_none(){ let cur=self.current_tab().current.clone(); let sh=self.show_hidden; let sb=self.current_tab().sort_by; let sd=self.current_tab().sort_desc; self.pane2=Some(Tab::new(cur,sh,sb,sd)); } } else{ self.pane2=None; self.active_pane=0; } self.sync_watchers(); }
}
